const inp = $input.first().json;
const b = inp.body || {};
const auth = (inp.headers && (inp.headers.authorization || inp.headers.Authorization)) || '';
if (!auth) return [{ json: { error: 'not_authenticated' } }];
let limit = parseInt(b.limit, 10);
if (!isFinite(limit)) limit = 5;
limit = Math.max(1, Math.min(15, limit));
return [{ json: { ok: true, auth: auth, limit: limit } }];

const caller = $input.first().json;
const req = $('Pre').first().json;
const role = (caller.app_metadata && caller.app_metadata.role) || '';
if (!caller.id) return [{ json: { error: 'not_authenticated' } }];
if (!['owner', 'admin', 'manager'].includes(role)) return [{ json: { error: 'forbidden' } }];
return [{ json: { ok: true, limit: req.limit } }];

// Собираем промпт «Рокфеллера» для одного лида. Модель меняется тут:
const MODEL = 'openai/gpt-4o-mini';
const SYS = 'Ты — «Рокфеллер», аналитик-обогатитель базы холодных лидов веб-студии Vertux (Санкт-Петербург; делает сайты и AI-виджеты малому бизнесу). По данным о компании (и HTML её сайта, если он есть) верни СТРОГО один JSON-объект без markdown и без пояснений, все тексты по-русски:
{"type": "creation"|"redesign", "issues": "...", "context": "...", "call_script": "...", "gen_prompt": "..."}
Правила:
- type=redesign ТОЛЬКО если у компании есть настоящий сайт (не соцсеть/каталог), иначе creation.
- issues: конкретные болячки текущего сайта в 1–3 предложениях (адаптивность, форма заявки, скорость, устаревший вид, https). Если сайта нет — одним предложением, сколько клиентов бизнес теряет без сайта в его нише.
- context: 2–4 коротких факта о компании для разговора (из текста сайта, рубрик, рейтинга) — то, что покажет клиенту «мы про вас узнали».
- call_script: живой скрипт холодного звонка по ступеням, дословные фразы менеджера, разговорный язык без канцелярита, привязанный к болячкам ИМЕННО этой компании. Формат: «Ступень 1 — Внимание: "..." Ступень 2 — Интерес: "..." Ступень 3 — Выгода: "..." Ступень 4 — Демка: "..." Ступень 5 — Закрытие: "..."». В ступени «Демка» предлагай бесплатную демо-версию сайта, которую мы уже сделали.
- gen_prompt: подробный промпт для ИИ-генератора демо-лендинга этой компании: роль (senior frontend + арт-директор), ниша и город, структура секций под нишу, стиль и палитра под характер бизнеса, реалистичные русские тексты без лорем-ипсум, кириллические шрифты self-host, адаптивность, форма заявки.';
const lead = $('Queue').item.json;
let html = typeof $json.data === 'string' ? $json.data : '';
html = html.replace(/<script[\s\S]*?</script>/gi, ' ').replace(/<style[\s\S]*?</style>/gi, ' ');
const text = html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').slice(0, 3500);
const hasViewport = /name=["']viewport/i.test(html);
const hasForm = /<form/i.test(html);
const user = 'КОМПАНИЯ: ' + (lead.company || '') + '
РУБРИКИ: ' + (lead.niche || '') + '
ГОРОД: ' + (lead.city || '') + '
РЕЙТИНГ 2GIS: ' + (lead.rating != null ? lead.rating : '—') + ' (' + (lead.reviews || 0) + ' отзывов)' + '
САЙТ: ' + (lead.site || 'нет') + (text ? '
ПРИЗНАКИ САЙТА: viewport meta ' + (hasViewport ? 'есть' : 'НЕТ') + ', форма заявки ' + (hasForm ? 'есть' : 'не найдена') + '
ТЕКСТ САЙТА (вырезка): ' + text : '');
return [{ json: { payload: { model: MODEL, messages: [{ role: 'system', content: SYS }, { role: 'user', content: user }], max_tokens: 1600, temperature: 0.6 }, leadId: lead.id, hasSite: !!lead.site } }];

const c = $input.first().json;
const raw = ((c.choices || [])[0] || { message: {} }).message.content || '';
const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
let obj = null;
try { obj = JSON.parse(raw.slice(s, e + 1)); } catch (err) {}
const prev = $('Build Prompt').item.json;
if (!obj || !obj.call_script) return [{ json: { skip: true, leadId: prev.leadId } }];
const cut = (x, n) => String(x || '').slice(0, n);
const t = obj.type === 'creation' ? 'creation' : (obj.type === 'redesign' && prev.hasSite ? 'redesign' : (prev.hasSite ? 'redesign' : 'creation'));
return [{ json: { skip: false, leadId: prev.leadId, type: t, issues: cut(obj.issues, 1500), context: cut(obj.context, 2000), call_script: cut(obj.call_script, 6000), gen_prompt: cut(obj.gen_prompt, 6000) } }];
